// Multi-user-safe entry: the YakYak token lives in the 'YakYak API' Bearer
// Auth credential, and Code nodes can't read credentials — so everything the
// old $env setup derived from the token must now arrive in the payload:
//   userId  — optional; enables adopt-by-name, import, ownership check and the
//             trailer/template default (there is no whoami endpoint to derive it)
//   apiBase — optional; defaults to https://api.yakyak.ai
// Fired either by the webhook or by a parent workflow (passthrough item).
let source = 'webhook';
let payload;
try { payload = $('Input event').first().json.body || {}; }
catch (e) { source = 'subworkflow'; payload = $json || {}; }
const target = payload.target || {};
const mode = target.mode || 'patch';
if (mode !== 'patch' && mode !== 'episode') throw new Error(`unknown target.mode "${mode}" (use "patch" or "episode")`);
return [{ json: {
  source, mode,
  base: payload.apiBase || 'https://api.yakyak.ai',
  userId: payload.userId || '',
  target,
  changes: payload.changes || {},
  importData: payload.importData || null,
  chatWebhookUrl: payload.chatWebhookUrl || '',
  needMovieLookup: !!(target.movieId && !target.campaignId),
} }];

// Campaign resolution, minus the token decoding the old version did in-code.
// 'Get movie for campaign' and 'List campaigns' ran (or not) per the IF gates,
// so their references here are safe exactly when the flags say they are.
// Never import per run: adopt the owned campaign by id or name; import only
// once as a fallback (the v1 import-per-run mistake created duplicates).
const ctx = $('Normalize input').first().json;
let derivedCampaignId = '';
if (ctx.needMovieLookup) {
  const g = $('Get movie for campaign').first().json;
  derivedCampaignId = ((g.movie || g).campaignId) || '';
  if (!derivedCampaignId) throw new Error(`get-movie ${ctx.target.movieId} returned no campaignId`);
}
let owned = null;
if (ctx.userId) owned = ($('List campaigns').first().json.campaigns) || [];

let campaignId = ctx.target.campaignId || derivedCampaignId;
let listEntry = null;
let needImport = false;
if (campaignId) {
  if (owned) {
    listEntry = owned.find((c) => c.id === campaignId) || null;
    if (!listEntry) throw new Error(`campaign ${campaignId} is not owned by this token's user`);
  }
} else {
  if (!owned) throw new Error('need target.campaignId, target.movieId, or body.userId — adopt-by-name and import go through list-campaign, and the userId can no longer be decoded from the token (it lives in a credential now)');
  const name = ctx.target.campaignName || (ctx.importData && ctx.importData.campaigns && ctx.importData.campaigns[0] && ctx.importData.campaigns[0].name) || '';
  if (!name) throw new Error('need target.campaignId, target.campaignName, or importData to resolve a campaign');
  // Oldest name match = the canonical original (later same-name copies are
  // v1-era import duplicates). Deterministic across runs.
  const matches = owned.filter((c) => c.name === name).sort((a, b) => String(a.createdAt).localeCompare(String(b.createdAt)));
  if (matches.length) { listEntry = matches[0]; campaignId = listEntry.id; }
  else if (ctx.importData) needImport = true;
  else throw new Error(`no owned campaign named "${name}" and no importData to provision one`);
}
return [{ json: { campaignId, needImport, templateId: (listEntry && listEntry.template && listEntry.template.id) || '' } }];

const r = $('Resolve campaign').first().json;
let campaignId = r.campaignId;
let provisioned = 'reused';
if (r.needImport) {
  const imported = $('Import campaign').first().json;
  campaignId = (imported.campaigns && imported.campaigns[0] && imported.campaigns[0].id) || '';
  if (!campaignId) throw new Error('import-campaign returned no campaign');
  provisioned = 'imported';
}
return [{ json: { campaignId, provisioned, templateId: r.templateId } }];

// Movie resolution — patch → trailer/template (or pinned movieId); episode →
// lowest unrendered slot, minting a season when full. The season wait that
// used to be an in-code sleep loop (capped by the Code node time limit) is now
// a real Wait-node loop: the not-ready output loops back via Wait 10s (season).
const ctx = $('Normalize input').first().json;
const a = $('Adopt campaign').first().json;
const campaignId = a.campaignId;
const movies = ((($json.campaign || $json).movies) || []).slice()
  .sort((x, y) => (Number(x.season) - Number(y.season)) || (Number(x.episode) - Number(y.episode)));
const done = (movieId) => [{ json: { ready: true, userId: ctx.userId, base: ctx.base, mode: ctx.mode, campaignId, movieId, provisioned: a.provisioned, chatWebhookUrl: ctx.chatWebhookUrl } }];

if (ctx.mode === 'patch') {
  const t = ctx.target || {};
  if (t.movieId) {
    // needMovieLookup means get-movie already proved this id exists and named
    // this campaign — and get-campaign lists only numbered episodes, so don't
    // re-check a trailer/template id against it.
    if (!ctx.needMovieLookup && !movies.some((m) => m.id === t.movieId) && t.movieId !== a.templateId) {
      throw new Error(`movie ${t.movieId} not found in campaign ${campaignId} (${movies.length} episode(s); template: ${a.templateId || 'none'})`);
    }
    return done(t.movieId);
  }
  if (a.templateId) return done(a.templateId);
  if (movies.length === 1) return done(movies[0].id); // no template and exactly one movie — unambiguous
  if (movies.length === 0) throw new Error(`campaign ${campaignId} has no template movie and no episodes to patch${ctx.userId ? '' : ' — pass body.userId so the template can be found via list-campaign'}`);
  const list = movies.map((m) => `S${m.season}E${m.episode}=${m.id}`).join(', ');
  throw new Error(`campaign ${campaignId} has no template movie and ${movies.length} episodes — pass target.movieId. Candidates: ${list}`);
}

// episode mode
const slot = movies.find((m) => !(m.renderedMovieUrl || ''));
if (slot) return done(slot.id);
let seasonKicked = false;
try { $('Create season').first(); seasonKicked = true; } catch (e) {}
if (seasonKicked) {
  if ($runIndex > 40) throw new Error('season creation is still in progress — re-run in a minute and it will pick up the new slot');
  return [{ json: { ready: false, poll: true } }];
}
if (movies.length > 0) {
  // every slot rendered → mint the next season
  return [{ json: { ready: false, poll: false, seasonPath: '/workflow/create-new-season', seasonBody: { campaignId } } }];
}
// fresh campaign, no numbered slots: create-new-season can't bootstrap from
// nothing (it 500s) — seed season 1 from the template movie.
if (!a.templateId) throw new Error(`campaign has no episode slots and no template movie to bootstrap from${ctx.userId ? '' : ' — pass body.userId so the template can be found via list-campaign'}`);
return [{ json: { ready: false, poll: false, seasonPath: '/workflow/gen-movie-season', seasonBody: { movieId: a.templateId } } }];

// Code nodes can't use credentials, so instead of calling the API from code we
// PLAN the calls here (diff-aware — the same skip rules as before, so a
// re-delivered trigger event doesn't re-bill unchanged scenes) and let the
// credentialed 'Execute change' HTTP node run them one item at a time.
// PATCH: each change maps to the update-scene-* endpoint that both persists
// the edit AND self-triggers the right regen cascade. EPISODE: write the new
// slot's plot and kick gen-movie-screenplay, which writes the whole screenplay
// AND renders every scene server-side (💸).
const t = $('Resolve target').first().json;
const changes = $('Normalize input').first().json.changes || {};
const movieId = t.movieId;
const calls = [];

if (changes.movie && changes.movie.title) calls.push({ path: '/workflow/update-movie-title', body: { movieId, title: changes.movie.title } });
// Optional soundtrack pin (content-address reuse — no upload, no generation).
// The path is a CDN content address; env prefixes (beta/, prd/) resolve in the
// shared bucket regardless of which env the campaign lives in (docs/forking.md).
if (changes.movie && changes.movie.soundtrackAudioPath) calls.push({ path: '/workflow/set-soundtrack-audio', body: { movieId, audioPath: changes.movie.soundtrackAudioPath } });
if (changes.movie && changes.movie.soundtrackVolume != null) calls.push({ path: '/workflow/set-soundtrack', body: { movieId, volumePercentage: Number(changes.movie.soundtrackVolume) } });

let changed = 0;
if (t.mode === 'episode') {
  if (!changes.movie || !changes.movie.plot) throw new Error('episode mode needs changes.movie.plot (the story text for the new episode)');
  calls.push({ path: '/workflow/set-movie-metadata', body: { movieId, plot: changes.movie.plot } });
  calls.push({ path: '/workflow/gen-movie-screenplay', body: { movieId } });
  changed = 1;
} else {
  const scenes = $('Get scenes').first().json.scenes || [];
  const byNumber = {};
  for (const s of scenes) byNumber[s.sceneNumber] = s;
  for (const ch of (changes.scenes || [])) {
    const scene = byNumber[ch.sceneNumber];
    if (!scene) continue;
    const sceneId = scene.id;
    switch (ch.action) {
      case 'story':
        if (scene.story === ch.story) continue; // no-op: skip (a redundant story costs an AI image gen)
        calls.push({ path: '/workflow/update-scene-story', body: { sceneId, story: ch.story } }); break;
      case 'dialogue':
        if (scene.dialogue === ch.dialogue) continue;
        calls.push({ path: '/workflow/update-scene-dialogue', body: { sceneId, dialogue: ch.dialogue } }); break;
      case 'animation': // current prompt isn't exposed by get-scenes; always apply
        calls.push({ path: '/workflow/update-scene-animation-prompt', body: { sceneId, prompt: ch.prompt } }); break;
      case 'styling': {
        let did = false;
        if (ch.leadCast != null && ch.leadCast !== scene.leadCast) { calls.push({ path: '/workflow/update-scene-lead-cast', body: { sceneId, leadCast: ch.leadCast } }); did = true; }
        if (ch.backgroundColor != null) {
          calls.push({ path: '/workflow/update-scene-background-color', body: { sceneId, backgroundColor: ch.backgroundColor } });
          calls.push({ path: '/workflow/rerun-scene', body: { sceneId, from: 'subtitle' } });
          did = true;
        }
        if (!did) continue;
        break;
      }
      case 'title':
        if (scene.title === ch.title) continue;
        calls.push({ path: '/workflow/update-scene-title', body: { sceneId, title: ch.title } }); break;
      case 'retry': calls.push({ path: '/workflow/rerun-scene', body: { sceneId, from: ch.from || 'image' } }); break;
      case 'regen': calls.push({ path: '/workflow/regen-scene-asset', body: { sceneId, asset: ch.asset || 'image' } }); break;
      default: throw new Error(`unknown action "${ch.action}" for scene ${ch.sceneNumber}`);
    }
    changed++;
  }
}
return [{ json: { calls, changed, movieId, mode: t.mode } }];

// Fan back in after the (possibly skipped) Execute change calls. Keeps the old
// node name so the downstream progress/response expressions stay identical to
// workflow.import-regen-post.json.
const p = $('Plan changes').first().json;
return [{ json: { movieId: p.movieId, mode: p.mode, changed: p.changed } }];

// PATCH: nothing changed → nothing to wait for (mirrors the reference script;
// a movie can legitimately report a stage as forever-pending — the dialogue-less
// outro scene has no subtitle/burn asset, so those stages sit at N-1/N with 0
// failed). Otherwise settled when done+failed >= total everywhere.
// EPISODE: the web app's completion signal — movieScreenplay completing;
// export-render then finishes any per-scene renders still in flight.
const mode = $('Resolve target').first().json.mode;
const changed = $('Apply changes').first().json.changed || 0;
if (changed === 0) return [{ json: { settled: true, failed: 0 } }];
if (mode === 'episode') {
  const ex = {};
  for (const e of ($json.executions || [])) ex[e.type] = e.status;
  if (ex.movieScreenplay === 'failed') throw new Error('screenplay generation failed');
  return [{ json: { settled: ex.movieScreenplay === 'completed', failed: 0 } }];
}
const steps = Object.values($json.steps || {});
const settled = steps.length === 0 || steps.every((s) => s.total === 0 || (s.done + s.failed) >= s.total);
const failed = steps.reduce((n, s) => n + (s.failed || 0), 0);
return [{ json: { settled, failed } }];

const ex = {};
for (const e of ($json.executions || [])) ex[e.type] = e.status;
if (ex.movieConcat === 'failed' || ex.movieSoundtrack === 'failed') throw new Error('render failed');
const done = ex.movieConcat === 'completed' && (ex.movieSoundtrack === undefined || ex.movieSoundtrack === 'completed');
return [{ json: { done } }];

const gm = $('Get movie').first().json;
const m = gm.movie || gm;
const t = $('Resolve target').first().json;
return [{ json: { url: m.finalMovieUrl || m.soundtrackedMovieUrl || m.concatMovieUrl || '', movieId: t.movieId, campaignId: t.campaignId, mode: t.mode, changed: $('Apply changes').first().json.changed } }];
